                      </AnimatePresence>
                    </div>
                  )}

                  {/* Authenticated Links - Desktop */}
                  <div className="hidden xl:flex items-center gap-1">
                    {getAuthenticatedLinks().map((item) => {
                      const Icon = item.icon;
                      return (
                        <button
