                        <Icon className="w-5 h-5" />
                        {item.label}
                      </Link>
                    );
                  })}
                </div>





























                {/* Authenticated Links for Mobile */}
                {isAuthenticated && (
                  <div className="space-y-1 pt-3">
                    <p className="px-3 py-1 text-xs font-semibold text-gray-500 dark:text-slate-400 uppercase tracking-wider">
                      Your Account
                    </p>
                    {getAuthenticatedLinks().map((item) => {
                      const Icon = item.icon;
                      return (
                        <Link
                          key={item.path}
                          to={item.path}
                          onClick={() => setMobileMenuOpen(false)}
                          className="flex items-center gap-3 px-4 py-3 rounded-xl text-gray-700 dark:text-slate-300 hover:bg-gray-100 dark:hover:bg-white/5 text-sm"
                        >
                          <Icon className="w-5 h-5" />
                          {item.label}
                        </Link>
                      );
                    })}
                  </div>
                )}

































                {/* Mobile Auth Buttons */}
                <div className="border-t border-gray-200 dark:border-white/10 pt-4 mt-4 space-y-2">
                  {isAuthenticated ? (
                    <>
                      <div className="flex items-center gap-3 px-4 py-3 bg-gray-50 dark:bg-white/5 rounded-xl">
                        <Avatar name={user?.name || 'User'} size="sm" src={user?.profileImage} />
                        <div>
                          <p className="text-sm font-medium text-gray-900 dark:text-white">
                            {user?.name}
                          </p>
                          <p className="text-xs text-gray-500 dark:text-slate-400">
                            {user?.email}
                          </p>
                        </div>
                      </div>
                      <button
                        onClick={handleLogout}
                        className="w-full flex items-center justify-center gap-2 px-4 py-3 rounded-xl bg-red-50 dark:bg-red-500/10 text-red-600 dark:text-red-400 text-sm font-medium"
                      >
                        <LogOut className="w-4 h-4" /> Sign Out
                      </button>
                    </>
                  ) : (
                    <>
                      <Link
                        to="/login"
                        onClick={() => setMobileMenuOpen(false)}
                        className="block w-full text-center px-4 py-3 rounded-xl text-gray-700 dark:text-slate-300 hover:bg-gray-100 dark:hover:bg-white/5 text-sm"
                      >
                        Sign In
                      </Link>
                      <Link
                        to="/register"
                        onClick={() => setMobileMenuOpen(false)}
                        className="block w-full text-center px-4 py-3 rounded-xl bg-gradient-to-r from-blue-500 to-teal-500 text-white text-sm font-semibold"
                      >
                        Get Started
                      </Link>
                    </>
                  )}
                </div>

                {/* Theme and Language Toggles for Mobile */}
                <div className="flex items-center justify-between pt-4 border-t border-gray-200 dark:border-white/10">
                  <button
                    onClick={() => setTheme(theme === 'dark' ? 'light' : 'dark')}
                    className="flex items-center gap-2 px-4 py-2 rounded-xl text-gray-700 dark:text-slate-300 hover:bg-gray-100 dark:hover:bg-white/5 text-sm"
                  >
                    {getThemeIcon()}
                    {theme === 'dark' ? 'Light Mode' : 'Dark Mode'}
                  </button>
                  
                  <button
                    onClick={() => setLanguage(lang => lang === 'en' ? 'es' : 'en')}
                    className="flex items-center gap-2 px-4 py-2 rounded-xl text-gray-700 dark:text-slate-300 hover:bg-gray-100 dark:hover:bg-white/5 text-sm"
                  >
                    <Globe className="w-4 h-4" />
                    {language === 'en' ? 'English' : 'Español'}
                  </button>
                </div>
              </div>
            </motion.div>
          )}
        </AnimatePresence>
      </motion.nav>

      {/* Mobile Menu Overlay */}
      <AnimatePresence>
        {mobileMenuOpen && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            onClick={() => setMobileMenuOpen(false)}
            className="fixed inset-0 bg-black/50 z-[998] md:hidden"
          />
        )}
      </AnimatePresence>
    </>
  );
};

import React, { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { 
  ChevronRight,
  ChevronLeft,
  LayoutDashboard,
  Building2 as Hospital,
  Stethoscope,
  Users,
  Calendar,
  Activity,
  Pill,
  Baby,
  FileText,
  Settings,
  LogOut
} from 'lucide-react';
import { useNavigate, useLocation } from 'react-router-dom';
import { useDispatch } from 'react-redux';
import { logout } from '../../store/slices/authSlice';
import { clsx } from 'clsx';
import { twMerge } from 'tailwind-merge';
import { Badge } from '../ui/Badge';

// ============================================
// TYPES & INTERFACES
// ============================================
export interface SidebarProps {
  variant?: 'glass' | 'gradient' | 'neon' | 'solid';
  collapsed?: boolean;
  onToggle?: () => void;
  activePath?: string;
  onNavigate?: (path: string) => void;
}

export interface SidebarItem {
  title: string;
  path: string;
  icon: React.ElementType;
  badge?: string | number;
  children?: SidebarItem[];
  pro?: boolean;
}

// ============================================
// VARIANT STYLES
// ============================================
const variantStyles = {
  glass: `
    bg-white/10 dark:bg-gray-900/10
    backdrop-blur-2xl backdrop-saturate-150
    border-r border-white/20 dark:border-gray-700/20
  `,
  gradient: `
    bg-gradient-to-b from-purple-600/90 via-pink-600/90 to-red-600/90
    backdrop-blur-xl
    border-r border-white/30
  `,
  neon: `
    bg-gray-900/95 dark:bg-black/95
    border-r-2 border-cyan-500/50
    shadow-[0_0_30px_rgba(6,182,212,0.3)]
  `,
  solid: `
    bg-white dark:bg-gray-800
    border-r border-gray-200 dark:border-gray-700
  `,
};

// ============================================
// SIDEBAR ITEMS DATA (All routes connected to routeConfig)
// ============================================
const sidebarItems: SidebarItem[] = [
  {
    title: 'Dashboard',
    path: '/patient/dashboard',
    icon: LayoutDashboard,
  },
  {
    title: 'Hospitals',
    path: '/hospital',
    icon: Hospital,
  },
  {
    title: 'Find Doctor',
    path: '/doctor',
    icon: Stethoscope,
    badge: 65,
  },
  {
    title: 'Appointments',
    path: '/appointments/list',
    icon: Calendar,
  },
  {
    title: 'Emergency',
    path: '/emergency',
    icon: Activity,
    badge: 'NEW',
  },
  {
    title: 'Pharmacy',
    path: '/pharmacy',
    icon: Pill,
  },
  {
    title: 'Women Care',
    path: '/women-care',
    icon: Baby,
    children: [
      {
        title: 'Dashboard',
        path: '/women-care',
        icon: Baby,
      },
      {
        title: 'Pregnancy Tracker',
        path: '/women-care/pregnancy',
        icon: Baby,
      },
      {
        title: 'Menstrual Cycle',
        path: '/women-care/menstrual-cycle',
        icon: FileText,
      },
      {
        title: 'Gynecologist',
        path: '/women-care/gynecologist',
        icon: Stethoscope,
      },
      {
        title: 'Vaccine Schedule',
        path: '/women-care/vaccine-schedule',
        icon: FileText,
      },
    ],
  },
  {
    title: 'AI Assistant',
    path: '/ai-assistant',
    icon: Activity,
  },
  {
    title: 'Oxygen',
    path: '/oxygen',
    icon: Activity,
  },
  {
    title: 'Blood Donors',
    path: '/blood-donors',
    icon: Users,
  },
  {
    title: 'About',
    path: '/about',
    icon: FileText,
  },
];

// ============================================
// SIDEBAR COMPONENT
// ============================================
export const Sidebar: React.FC<SidebarProps> = ({
  variant = 'glass',
  collapsed = false,
  onToggle,
  activePath: activePathProp,
  onNavigate: onNavigateProp,
}) => {
  const navigate = useNavigate();
  const location = useLocation();
  const dispatch = useDispatch();
  const activePath = activePathProp || location.pathname;
  const [openSubmenu, setOpenSubmenu] = useState<string | null>(null);

  const handleNavigate = (path: string) => {
    if (path === '/logout') {
      dispatch(logout());
      sessionStorage.clear();
      navigate('/login');
      return;
    }
    if (onNavigateProp) {
      onNavigateProp(path);
    } else {
      navigate(path);
    }
  };

  const handleItemClick = (item: SidebarItem) => {
    if (item.children) {
      setOpenSubmenu(openSubmenu === item.path ? null : item.path);
    } else {
      handleNavigate(item.path);
    }
  };

  return (
    <motion.aside
      className={twMerge(
        clsx(
          'fixed left-0 top-20 bottom-0 z-40',
          collapsed ? 'w-20' : 'w-72',
          'transition-all duration-300',
          variantStyles[variant],
          'transform-gpu'
        )
      )}
      initial={{ x: -300 }}
      animate={{ x: 0 }}
      transition={{ type: 'spring', stiffness: 300, damping: 30 }}
    >
      {/* Toggle Button */}
      <motion.button
        whileHover={{ scale: 1.1 }}
        whileTap={{ scale: 0.9 }}
        onClick={onToggle || (() => {})}
        className={clsx(
          'absolute -right-3 top-6 w-8 h-8',
          'bg-white/20 dark:bg-gray-700/50',
          'border border-white/30 dark:border-gray-600',
          'rounded-full flex items-center justify-center',
          'text-white backdrop-blur-sm',
          'hover:bg-white/30 transition-colors'
        )}
      >
        {collapsed ? (
          <ChevronRight className="w-4 h-4" />
        ) : (
          <ChevronLeft className="w-4 h-4" />
        )}
      </motion.button>

      {/* Sidebar Content */}
      <div className="h-full flex flex-col py-6 overflow-hidden">
        {/* Menu Items */}
        <div className="flex-1 overflow-y-auto custom-scrollbar px-4">
          {sidebarItems.map((item, index) => {
            const isActive = activePath === item.path || activePath.startsWith(item.path + '/');
            const isOpen = openSubmenu === item.path;
            const Icon = item.icon;

            return (
              <motion.div
                key={item.path}
                initial={{ opacity: 0, x: -20 }}
                animate={{ opacity: 1, x: 0 }}
                transition={{ delay: index * 0.05, type: 'spring' }}
                className="mb-2"
              >
                {/* Main Item */}
                <motion.button
                  whileHover={{ x: collapsed ? 0 : 5, scale: 1.02 }}
                  whileTap={{ scale: 0.98 }}
                  onClick={() => handleItemClick(item)}
                  className={clsx(
                    'w-full flex items-center gap-4 px-4 py-3 rounded-2xl',
                    'transition-all duration-300 relative overflow-hidden',
                    isActive
                      ? 'bg-white/20 dark:bg-gray-700/50 text-white'
                      : 'text-white/70 hover:bg-white/10 dark:hover:bg-gray-700/30',
                    'group'
                  )}
                >
                  {/* Icon */}
                  <Icon className={clsx(
                    'w-6 h-6 flex-shrink-0',
                    isActive && 'text-white',
                    !collapsed && 'text-white/70 group-hover:text-white'
                  )} />

                  {/* Title & Badge */}
                  {!collapsed && (
                    <div className="flex-1 flex items-center justify-between">
                      <span className="font-medium text-sm">{item.title}</span>
                      <div className="flex items-center gap-2">
                        {item.badge && (
                          <Badge size="xs" variant={isActive ? 'primary' : 'default'}>
                            {item.badge}
                          </Badge>
                        )}
                        {item.pro && (
                          <Badge size="xs" variant="gradient">
                            PRO
                          </Badge>
                        )}
                        {item.children && (
                          <ChevronRight className={clsx(
                            'w-4 h-4 transition-transform',
                            isOpen && 'rotate-90'
                          )} />
                        )}
                      </div>
                    </div>
                  )}

                  {/* Active Indicator */}
                  {isActive && !collapsed && (
                    <motion.div
                      layoutId="activeIndicator"
                      className="absolute left-0 top-0 bottom-0 w-1 bg-cyan-400 rounded-r-full"
                    />
                  )}
                </motion.button>

                {/* Submenu */}
                <AnimatePresence>
                  {item.children && isOpen && !collapsed && (
                    <motion.div
                      initial={{ height: 0, opacity: 0 }}
                      animate={{ height: 'auto', opacity: 1 }}
                      exit={{ height: 0, opacity: 0 }}
                      className="ml-10 mt-1 overflow-hidden"
                    >
                      {item.children.map((child, childIndex) => {
                        const ChildIcon = child.icon;
                        const isChildActive = activePath === child.path;

                        return (
                          <motion.button
                            key={child.path}
                            initial={{ opacity: 0, x: -10 }}
                            animate={{ opacity: 1, x: 0 }}
                            transition={{ delay: childIndex * 0.05 }}
                            onClick={() => handleNavigate(child.path)}
                            className={clsx(
                              'w-full flex items-center gap-3 px-4 py-2 rounded-xl mb-1',
                              'text-white/60 hover:text-white hover:bg-white/10',
                              'transition-all duration-300',
